{"command":"create","path":"/workspace/app-setup/schema.sql","file_text":"BEGIN;
DROP SCHEMA IF EXISTS labapp CASCADE;
CREATE SCHEMA labapp;
SET search_path=labapp,public;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, password_hash text NOT NULL,
 email text, full_name text, phone text, roles text[] NOT NULL DEFAULT '{}', qualifications text[] NOT NULL DEFAULT '{}',
 certifications jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT true, assigned_location_id uuid,
 available boolean NOT NULL DEFAULT true, capacity_units integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE sessions (token text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, active_role text NOT NULL DEFAULT '', expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);

CREATE TABLE sample_types (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, qualified_collector_required boolean NOT NULL DEFAULT false,
 required_qualification text NOT NULL DEFAULT '', container_type text NOT NULL, temperature_min_c numeric NOT NULL,
 temperature_max_c numeric NOT NULL, incompatible_sample_types uuid[] NOT NULL DEFAULT '{}', requires_cooled_route boolean NOT NULL DEFAULT false,
 batching_allowed boolean NOT NULL DEFAULT true, active boolean NOT NULL DEFAULT true,
 CHECK (temperature_min_c <= temperature_max_c)
);
CREATE TABLE locations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90),
 longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), coverage_km numeric NOT NULL DEFAULT 5 CHECK(coverage_km > 0 AND coverage_km <= 5),
 handling_minutes integer NOT NULL DEFAULT 0 CHECK(handling_minutes BETWEEN 0 AND 1440), active boolean NOT NULL DEFAULT true,
 functions jsonb NOT NULL DEFAULT '{"collection_point":false,"transfer_point":false,"hub":false,"laboratory":false}'
);
CREATE TABLE capacities (resource_id uuid PRIMARY KEY, capacity_units integer NOT NULL DEFAULT 0 CHECK(capacity_units>=0), reserved_units integer NOT NULL DEFAULT 0 CHECK(reserved_units>=0), cooled_capacity_units integer NOT NULL DEFAULT 0 CHECK(cooled_capacity_units>=0), cooled_reserved_units integer NOT NULL DEFAULT 0 CHECK(cooled_reserved_units>=0), CHECK(reserved_units<=capacity_units), CHECK(cooled_reserved_units<=cooled_capacity_units));
CREATE TABLE connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_location_id uuid NOT NULL REFERENCES locations(id), to_location_id uuid NOT NULL REFERENCES locations(id), travel_minutes integer NOT NULL CHECK(travel_minutes>0), cost_units numeric NOT NULL CHECK(cost_units>=0), cooled boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, UNIQUE(from_location_id,to_location_id));
CREATE INDEX connections_route_idx ON connections(from_location_id,to_location_id) WHERE active;
CREATE TABLE lab_acceptance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), laboratory_id uuid NOT NULL REFERENCES locations(id), sample_type_id uuid NOT NULL REFERENCES sample_types(id), accepts boolean NOT NULL, UNIQUE(laboratory_id,sample_type_id));

CREATE TABLE requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL REFERENCES users(id), origin jsonb NOT NULL, origin_type text NOT NULL, origin_node_id uuid, requested_at timestamptz NOT NULL, earliest_collection_at timestamptz NOT NULL, latest_collection_at timestamptz NOT NULL, delivery_deadline timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX requests_requester_idx ON requests(requester_id);
CREATE TABLE samples (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES requests(id), sample_type_id uuid NOT NULL REFERENCES sample_types(id),
 container_type text NOT NULL, temperature_min_c numeric NOT NULL, temperature_max_c numeric NOT NULL, incompatible_sample_types uuid[] NOT NULL DEFAULT '{}',
 status text NOT NULL, serviceability text NOT NULL, serviceability_reason text, current_holder_id uuid REFERENCES users(id), target_laboratory_id uuid REFERENCES locations(id),
 active_journey_id uuid, sealed_at timestamptz, received_at timestamptz, latest_location jsonb, location_recorded_at timestamptz, exception jsonb,
 already_sealed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX samples_request_idx ON samples(request_id); CREATE INDEX samples_status_idx ON samples(status);
CREATE TABLE journeys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_journey_id uuid, plan_version integer NOT NULL DEFAULT 1, route_mode text NOT NULL DEFAULT 'direct', status text NOT NULL DEFAULT 'active', estimated_delivery_at timestamptz, total_cost_units numeric NOT NULL DEFAULT 0, capacity_used integer NOT NULL DEFAULT 1, sample_ids uuid[] NOT NULL, ordered_stops jsonb NOT NULL DEFAULT '[]', valid boolean NOT NULL DEFAULT true, replan_status text, replacement_journey_id uuid, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE samples ADD CONSTRAINT samples_journey_fk FOREIGN KEY(active_journey_id) REFERENCES journeys(id);
CREATE TABLE assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journey_id uuid NOT NULL REFERENCES journeys(id), sample_id uuid NOT NULL REFERENCES samples(id), kind text NOT NULL, sequence integer NOT NULL, from_location_id uuid, to_location_id uuid, worker_id uuid REFERENCES users(id), offered_to uuid REFERENCES users(id), status text NOT NULL DEFAULT 'offered', offer_expires_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX assignments_worker_idx ON assignments(worker_id,status); CREATE INDEX assignments_journey_idx ON assignments(journey_id,sequence);
CREATE TABLE handoffs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sample_id uuid NOT NULL REFERENCES samples(id), from_assignment_id uuid NOT NULL REFERENCES assignments(id), to_assignment_id uuid NOT NULL REFERENCES assignments(id), sender_id uuid NOT NULL REFERENCES users(id), receiver_id uuid NOT NULL REFERENCES users(id), sender_confirmed boolean NOT NULL DEFAULT false, receiver_confirmed boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'pending', initiated_at timestamptz NOT NULL, completed_at timestamptz, UNIQUE(sample_id,from_assignment_id,to_assignment_id));
CREATE TABLE checkpoints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sample_id uuid NOT NULL REFERENCES samples(id), assignment_id uuid NOT NULL REFERENCES assignments(id), location_id uuid, container_type text NOT NULL, observed_temperature_c numeric NOT NULL, compliant boolean NOT NULL, recorded_at timestamptz NOT NULL);
CREATE TABLE capacity_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journey_id uuid NOT NULL REFERENCES journeys(id), resource_id uuid NOT NULL REFERENCES capacities(resource_id), cooled boolean NOT NULL, units integer NOT NULL CHECK(units>0), active boolean NOT NULL DEFAULT true, UNIQUE(journey_id,resource_id,cooled));

CREATE TABLE audit_log (id bigserial PRIMARY KEY, audit_id uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(), actor_id uuid, role text NOT NULL DEFAULT '', action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, success boolean NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), details jsonb NOT NULL DEFAULT '{}');
CREATE INDEX audit_entity_idx ON audit_log(entity_type,entity_id,occurred_at DESC); CREATE INDEX audit_actor_idx ON audit_log(actor_id,occurred_at DESC); CREATE INDEX audit_action_idx ON audit_log(action);
CREATE TABLE realtime_events (id bigserial PRIMARY KEY, type text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency (actor_id uuid NOT NULL, operation text NOT NULL, key text NOT NULL, request_hash text NOT NULL, status integer NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,operation,key));
CREATE TABLE disruptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resource_type text NOT NULL, resource_id uuid NOT NULL, reason text, occurred_at timestamptz NOT NULL, result jsonb NOT NULL);
CREATE TABLE serviceability_snapshots (version integer PRIMARY KEY, status text NOT NULL CHECK(status='complete'), computed_at timestamptz NOT NULL, network_revision integer NOT NULL, regions jsonb NOT NULL);

INSERT INTO sample_types(name,qualified_collector_required,required_qualification,container_type,temperature_min_c,temperature_max_c,requires_cooled_route,batching_allowed) VALUES
 ('Amber',true,'Amber','standard',2,25,false,true),('Indigo',true,'Indigo','indigo-safe',2,25,false,true),('Frost',true,'Frost','cooled',2,8,true,true),('Pulse',true,'Pulse','priority',2,25,false,false);
UPDATE sample_types SET incompatible_sample_types=ARRAY[(SELECT id FROM sample_types WHERE name='Amber')] WHERE name='Indigo';
UPDATE sample_types SET incompatible_sample_types=ARRAY[(SELECT id FROM sample_types WHERE name='Indigo')] WHERE name='Amber';
INSERT INTO serviceability_snapshots VALUES(1,'complete',now(),1,'[]');
COMMIT;
