iest:e.target.value})}/></label><label>Latest collection<input aria-label="Latest collection" type="datetime-local" required value={f.latest} onChange={e=>setF({...f,latest:e.target.value})}/></label><label className="wide">Laboratory delivery deadline<input aria-label="Delivery deadline" type="datetime-local" required value={f.deadline} onChange={e=>setF({...f,deadline:e.target.value})}/></label></div><div className="form-actions"><button type="button" className="ghost" onClick={dry}>Check serviceability</button><button type="submit" className="primary" disabled={!check?.serviceable}>Create request →</button></div>{check&&<div className={check.serviceable?'success':'alert'}><b>{check.serviceable?'Serviceable':'Not serviceable'}</b> · {check.reason.replaceAll('_',' ')}<small>Dry run · no capacity reserved · version {check.serviceabilityVersion}</small></div>}</form>}
